using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;
public static class StudioBevelRenderValidation {
 public static void Run(){int exit=0;var doc=ScriptableObject.CreateInstance<StudioModelDocument>();GameObject renderObject=null;MeshFilter renderFilter=null;Mesh mesh=null;Material material=null;RenderTexture target=null;try{
 mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var polygons);doc.nodes.Add(new StudioModelDocument.Node{name="Cube",mesh=mesh,cutPolygons=polygons,cutTriangles=mesh.triangles});renderObject=new GameObject("Bevel GPU render validation");renderFilter=renderObject.AddComponent<MeshFilter>();renderFilter.sharedMesh=mesh;material=new Material(Shader.Find("Hidden/StudioValidationSolid"));target=new RenderTexture(256,256,24);target.Create();
 Color32[] Render(){var previous=RenderTexture.active;RenderTexture.active=target;GL.PushMatrix();GL.Clear(true,true,Color.black);GL.LoadProjectionMatrix(Matrix4x4.Ortho(-.85f,.85f,-.85f,.85f,.01f,10));GL.modelview=Matrix4x4.TRS(new Vector3(0,0,3),Quaternion.identity,Vector3.one).inverse;material.SetPass(0);Graphics.DrawMeshNow(renderFilter.sharedMesh,Matrix4x4.Rotate(Quaternion.Euler(20,35,0)));GL.PopMatrix();var texture=new Texture2D(256,256,TextureFormat.RGBA32,false);texture.ReadPixels(new Rect(0,0,256,256),0,0);texture.Apply();var pixels=texture.GetPixels32();UnityEngine.Object.DestroyImmediate(texture);RenderTexture.active=previous;return pixels;}
 var source=Render();if(source.Count(p=>p.r>200)<1000)throw new Exception("Render fixture produced no shaded geometry");using(var preview=new StudioMeshToolPreview(doc,new[]{0})){var t=preview.Targets[0];var edges=t.Topology.Faces.SelectMany(f=>Enumerable.Range(0,f.Vertices.Count).Select(i=>(f.Vertices[i],f.Vertices[(i+1)%f.Vertices.Count]))).ToArray();foreach(bool local in new[]{false,true}){if(local){preview.Restore();t.Reset();edges=edges.Where(e=>Math.Abs(t.Topology.Positions[e.Item1].y-.5f)<1e-6f&&Math.Abs(t.Topology.Positions[e.Item2].y-.5f)<1e-6f&&Math.Abs(t.Topology.Positions[e.Item1].z-.5f)<1e-6f&&Math.Abs(t.Topology.Positions[e.Item2].z-.5f)<1e-6f).ToArray();if(edges.Length==0)throw new Exception("No front edge for partial GPU range fixture");}Color32[] first=null;foreach(float width in new[]{.1f,.8f,.3f}){var result=t.Topology.BevelEdges(t.Work,edges,new StudioMeshCuts.BevelOptions{Width=width,Subdivisions=3,Tension=1});t.VertexUpdate=result.VertexUpdate;t.VertexUpdateStart=result.VertexUpdateStart;t.PublishedPositions=result.PublishedPositions;if(local&&result.VertexUpdateStart==0)throw new Exception("Partial upload fixture has no static prefix");t.IsBevelPreview=true;preview.Publish(true);t.UseGpuPreview(renderFilter);if(renderFilter.sharedMesh==mesh)throw new Exception("GPU preview mirror was not attached");var pixels=Render();if(pixels.SequenceEqual(source))throw new Exception("Rendered bevel unchanged from source");if(first==null)first=pixels;else if(pixels.SequenceEqual(first))throw new Exception("Live width leaves stale GPU geometry");if(width==.3f){var image=new Texture2D(256,256,TextureFormat.RGBA32,false);image.SetPixels32(pixels);image.Apply();File.WriteAllBytes(Path.GetFullPath(Path.Combine(Application.dataPath,"../../bevel-publication-render.png")),image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}}
 preview.Restore();}if(!Render().SequenceEqual(source))throw new Exception("Rendered cancellation did not restore source");}
 File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../bevel-render-validation.txt")),"PASS: existing live Mesh renders successive cached width updates and cancellation");}catch(Exception e){exit=1;File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../bevel-render-validation.txt")),e.ToString());}finally{if(renderObject)UnityEngine.Object.DestroyImmediate(renderObject);if(target)UnityEngine.Object.DestroyImmediate(target);if(material)UnityEngine.Object.DestroyImmediate(material);if(mesh)UnityEngine.Object.DestroyImmediate(mesh);UnityEngine.Object.DestroyImmediate(doc);}EditorApplication.Exit(exit);}
}
